head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil71203";
scwin.daily = null;
scwin.sometimes = null;
scwin.if_3or4 = null;
scwin.earyNum = 1;
scwin.form = null;
scwin.earyRedmptValuDdList = undefined;
scwin.earyRedmptBas1IdxList = undefined;
scwin.earyRedmptBas2IdxList = undefined;
scwin.earyRedmptPrcList = undefined;
scwin.earyRedmptPayDdList = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "txa_expEarngStructDscVal", attr: "label", fn: function () { return String(dma_readDataVO.get("expEarngStructDscVal")); } },
        { childId: "__rb7", attr: "label", fn: function () { return String(dma_readDataVO.get("valuPrc1HistVoltPd")) + " 개월"; } },
        { childId: "__rb8", attr: "label", fn: function () { return String(dma_readDataVO.get("valuPrc2HistVoltPd")) + " 개월"; } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_65", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '702' || (dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '704'); } }, { id: "tr_66", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '702' || (dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '704'); } }, { id: "c_otherwise_71", fn: function(){ return (!(((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '702' || (dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '704'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(dma_readDataVO.get("expMaxYd")) + " (%)"; } },
        { childId: "__rb1", fn: function () { return String(dma_readDataVO.get("expMaxRedmptPrc")) + " (원)"; } },
        { childId: "__rb2", fn: function () { return String(dma_readDataVO.get("expMaxLossRt")) + " (%)"; } },
        { childId: "__rb3", fn: function () { return String(dma_readDataVO.get("expMinRedmptPrc")) + " (원)"; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.earyRedmptCondYn();
        scwin.earyRedmptCondRelCd();
        scwin.insertComma(2);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71203.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldfil71203: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

try { scwin.earyRedmptValuDdList =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil71203' }); }

try { scwin.earyRedmptBas1IdxList =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil71203' }); }

try { scwin.earyRedmptBas2IdxList =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil71203' }); }

try { scwin.earyRedmptPrcList =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil71203' }); }

try { scwin.earyRedmptPayDdList =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil71203' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.daily = $c.util.getComponent('daily');
        scwin.sometimes = $c.util.getComponent('sometimes');
        scwin.if_3or4 = $c.util.getComponent('if_3or4');
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil71203.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「목록보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil71203c.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name __ev_2_btn_Search_onclick
 * @description __ev_2_btn_Search 클릭 이벤트
