 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__ev_2_btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71203.__ev_2_btn_Search_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_EtnChangePage
 * @description Etn Change Page 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_EtnChangePage = async function () {
    const sbmOptions = {
        id: "tx_fn_EtnChangePage",
        method: "post",
        action: "/etn/LossLimitEtnList.do",
        ref: "dma_EtnChangePageReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/etn/EtnList.do",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name etnChangePage
 * @description etn Change Page 처리
 * @param {*} tab tab
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.etnChangePage = async function (tab) {
    scwin.form = (document.etnListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent("dma_EtnChangePageReq").get("lastSaveStatCd"));
    if (tab === 1) {
        $c.util.getComponent("dma_EtnChangePageReq").set("method", 'lossLimitViewIsuTab');
    } else {
        if (tab === 2) {
            return;
        } else {
            if (tab === 3) {
                $c.util.getComponent("dma_EtnChangePageReq").set("method", 'lossLimitViewIsurTab');
            } else {
                if (tab === 4) {
                    $c.util.getComponent("dma_EtnChangePageReq").set("method", 'lossLimitViewSrtyLpTab');
                } else {
                    $c.util.getComponent("dma_EtnChangePageReq").set("method", 'lossLimitViewAttachFileTab');
                }
            }
        }
    }
    scwin.form.action = 'LossLimitEtnList.do';
    await scwin.tx_fn_EtnChangePage();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    scwin.form = (document.etnListForm || { elements: [] });
    scwin.form.action = "EtnList.do";
    $c.util.getComponent("dma_EtnChangePageReq").set("listBzTpCd", "");
    $c.util.getComponent("dma_EtnChangePageReq").set("method", 'searchList');
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name earyRedmptCondYn
 * @description eary Redmpt Cond Yn 처리
 * @returns {void}
 * @hidden N
 */
scwin.earyRedmptCondYn = function () {
    let obj = $c.util.getComponent('slc_earyRedmptCondYn').getValue(); if (obj == null) { obj = ''; }
    if (obj === 'N') {
        $c.util.getComponent('slc_earyRedmptCycleCd').setValue("");
        (($c.util.getComponent('slc_earyRedmptCycleCd')) && ($c.util.getComponent('slc_earyRedmptCycleCd')).setDisabled ? ($c.util.getComponent('slc_earyRedmptCycleCd')).setDisabled(('true') === 'disabled' || ('true') === 'readonly' || ('true') === 'checked' ? true : ('true')) : void 0);
    } else {

    }
    scwin.earyRedmptCycleCd();
};

/**
 * @method
 * @name earyRedmptCycleCd
 * @description eary Redmpt Cycle Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.earyRedmptCycleCd = function () {
    let obj = $c.util.getComponent('slc_earyRedmptCycleCd').getValue(); if (obj == null) { obj = ''; }
    if (obj === '') {
        scwin.daily.setStyle("display", "none");
        scwin.sometimes.setStyle("display", "none");
    } else {
        if (obj === '01') {
            scwin.daily.setStyle("display", "");
            scwin.sometimes.setStyle("display", "none");
        } else {
            scwin.daily.setStyle("display", "none");
            scwin.sometimes.setStyle("display", "");
        }
    }
};

/**
 * @method
 * @name addEaryRedmptCond
 * @description add Eary Redmpt Cond 처리
 * @returns {void}
 * @hidden N
 */
scwin.addEaryRedmptCond = function () {
    const earyCondRelCd = $c.util.getComponent('slc_earyRedmptCondRelCd').getValue();
    let sgnVal1, sgnVal2;
    if (earyCondRelCd === '1') {
        sgnVal1 = '<option value="1">이상</option>';
    } else {
        if (earyCondRelCd === '2') {
            sgnVal1 = '<option value="1">이하</option>';
        } else {
            if (earyCondRelCd === '3') {
                sgnVal1 = '<option value="1">이상</option>';
                sgnVal2 = '<option value="2">이하</option>';
            } else {
                if (earyCondRelCd === '4') {
                    sgnVal1 = '<option value="2">이하</option>';
                    sgnVal2 = '<option value="1">이상</option>';
                }
            }
        }
    }
    scwin.earyNum++;
    const language = $c.util.getComponent("earyRedptCond1");
    let txt = '		<div style="border-top: solid 1px; padding: 10px;">';
    txt += '			<div style="padding-bottom:5px;">';
    txt += '				<b>' + scwin.earyNum + '차</b>';
    txt += '				<span style="padding-left:5px;">';
    txt += '					조기상환 평가일 <input type="text" name="earyRedmptValuDd" id="earyRedmptValuDd' + scwin.earyNum + '" value="" class="form_search" size="10"  maxlength="8" alt="조기상환평가일" disabled="disabled" />';
    txt += '				</span>';
    txt += '			</div>';
    txt += '			<div style="padding-left:26px;padding-bottom:5px;">';
    txt += '				<span>조기상환 기준</span>';
    txt += '				<span style="padding-left:16px;">';
    txt += '					기초지수가 ';
    txt += '					<input type="text" name="earyRedmptBas1Idx" id="earyRedmptBas1Idx" value="" class="form_search_money" size="10" disabled="disabled" />';
    txt += '					<select name="sgn1" id="sgn1" class="form_select" disabled="disabled">' + sgnVal1 + '</select> ';
    if (earyCondRelCd === '3') {
        txt += '					<span id="if_3">또는 </span>';
    }
    if (earyCondRelCd === '4') {
        txt += '					<span id="if_4">이면서 </span>';
    }
    if (earyCondRelCd === '3' || earyCondRelCd === '4') {
        txt += '					<span id="if_3or4">';
        txt += '						<input type="text" name="earyRedmptBas2Idx" id="earyRedmptBas2Idx" value="" class="form_search_money" size="10" disabled="disabled" />';
        txt += '						<select name="sgn2" id="sgn2" class="form_select" disabled="disabled">' + sgnVal2 + '</select>';
        txt += '					</span>	';
    }
    txt += '					인 경우';
    txt += '				</span>';
    txt += '			</div>';
    txt += '			<div style="padding-left:26px;">';
    txt += '				조기상환가격(제비용 차감전) <input type="text" name="earyRedmptPrc" id="earyRedmptPrc" value="" class="form_search_money" size="10" disabled="disabled" />(원)';
    txt += '				조기상환 지급일 <input type="text" name="earyRedmptPayDd" id="earyRedmptPayDd' + scwin.earyNum + '" value="" class="form_search" size="10"  maxlength="8" alt="조기상환지급일" disabled="disabled" />';
    txt += '			</div>';
    txt += '		</div>';
    const addedDiv = document.createElement("div");
    addedDiv.id = "earyRedptCond" + scwin.earyNum;
    addedDiv.innerHTML = txt;
    language.appendChild(addedDiv);
};

/**
 * @method
 * @name setEaryRedmpt
 * @description set Eary Redmpt 처리
 * @returns {void}
 * @hidden N
 */
scwin.setEaryRedmpt = function () {
    for (let __i = 0; __i < (function(){ throw 'unresolved:list:redmptSometimesDataVO'; })(); __i++) {
        scwin.earyRedmptValuDdList[__i] = (String(((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })()) == null ? '' : ((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })())).indexOf('$' + '{') >= 0 ? '' : String(((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })()) == null ? '' : ((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })())));
        scwin.earyRedmptBas1IdxList[__i] = (String(((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })()) == null ? '' : ((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })())).indexOf('$' + '{') >= 0 ? '' : String(((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })()) == null ? '' : ((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })())));
        scwin.earyRedmptBas2IdxList[__i] = (String(((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })()) == null ? '' : ((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })())).indexOf('$' + '{') >= 0 ? '' : String(((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })()) == null ? '' : ((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })())));
        scwin.earyRedmptPrcList[__i] = (String(((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })()) == null ? '' : ((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })())).indexOf('$' + '{') >= 0 ? '' : String(((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })()) == null ? '' : ((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })())));
        scwin.earyRedmptPayDdList[__i] = (String(((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })()) == null ? '' : ((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })())).indexOf('$' + '{') >= 0 ? '' : String(((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })()) == null ? '' : ((function(){ throw 'unresolved:list:redmptSometimesDataVO'; })())));
    }
    const frm = (document.etnListForm || { elements: [] });
    for (let i = 0; i < scwin.earyRedmptValuDdList.length; i++) {
        if (i === 0) {
            $c.util.getComponent("ipt_earyRedmptValuDd1").setValue(scwin.earyRedmptValuDdList[i]);
            $c.util.getComponent("ipt_earyRedmptBas1Idx").setValue(scwin.earyRedmptBas1IdxList[i]);
            if ($c.util.getComponent('slc_earyRedmptCondRelCd').getValue() === '3' || $c.util.getComponent('slc_earyRedmptCondRelCd').getValue() === '4') {
                $c.util.getComponent("ipt_earyRedmptBas2Idx").setValue(scwin.earyRedmptBas2IdxList[i]);
            }
            $c.util.getComponent("ipt_earyRedmptPrc").setValue(scwin.earyRedmptPrcList[i]);
            $c.util.getComponent("ipt_earyRedmptPayDd1").setValue(scwin.earyRedmptPayDdList[i]);
        } else {
            scwin.addEaryRedmptCond();
            $c.util.getComponent('ipt_earyRedmptValuDd1')[i].value = scwin.earyRedmptValuDdList[i];
            $c.util.getComponent(["ipt_earyRedmptBas1Idx0", "ipt_earyRedmptBas1Idx"][i]).setValue(scwin.earyRedmptBas1IdxList[i]);
            if ($c.util.getComponent('slc_earyRedmptCondRelCd').getValue() === '3' || $c.util.getComponent('slc_earyRedmptCondRelCd').getValue() === '4') {
                $c.util.getComponent('ipt_earyRedmptBas2Idx')[i].value = scwin.earyRedmptBas2IdxList[i];
            }
            $c.util.getComponent(["ipt_earyRedmptPrc0", "ipt_earyRedmptPrc"][i]).setValue(scwin.earyRedmptPrcList[i]);
            $c.util.getComponent('ipt_earyRedmptPayDd1')[i].value = scwin.earyRedmptPayDdList[i];
        }
    }
};

/**
 * @method
 * @name earyRedmptCondRelCd
 * @description eary Redmpt Cond Rel Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.earyRedmptCondRelCd = function () {
    let obj = $c.util.getComponent('slc_earyRedmptCondRelCd').getValue(); if (obj == null) { obj = ''; }
    if (obj === '1') {
        $c.util.getComponent('if_3').setStyle("display", "none");
        $c.util.getComponent('if_4').setStyle("display", "none");
        scwin.if_3or4.setStyle("display", "none");
        $('#slc_sgn1 option').remove();
        $('#slc_sgn2 option').remove();
        $c.util.getComponent('slc_sgn1').addItem("1", "이상");
    } else {
        if (obj === '2') {
            $c.util.getComponent('if_3').setStyle("display", "none");
            $c.util.getComponent('if_4').setStyle("display", "none");
            scwin.if_3or4.setStyle("display", "none");
            $('#slc_sgn1 option').remove();
            $('#slc_sgn2 option').remove();
            $c.util.getComponent('slc_sgn1').addItem("2", "이하");
        } else {
            if (obj === '3') {
                $c.util.getComponent('if_3').setStyle("display", "");
                $c.util.getComponent('if_4').setStyle("display", "none");
                scwin.if_3or4.setStyle("display", "");
                $('#slc_sgn1 option').remove();
                $('#slc_sgn2 option').remove();
                $c.util.getComponent('slc_sgn1').addItem("1", "이상");
                $c.util.getComponent('slc_sgn2').addItem("2", "이하");
            } else {
                if (obj === '4') {
                    $c.util.getComponent('if_3').setStyle("display", "none");
                    $c.util.getComponent('if_4').setStyle("display", "");
                    scwin.if_3or4.setStyle("display", "");
                    $('#slc_sgn1 option').remove();
                    $('#slc_sgn2 option').remove();
                    $c.util.getComponent('slc_sgn1').addItem("2", "이하");
                    $c.util.getComponent('slc_sgn2').addItem("1", "이상");
                }
            }
        }
    }
    if (obj === $) {
        earyRedmptCondRelCdSet;
    }
    scwin.setEaryRedmpt();
};

/**
 * @method
 * @name insertComma
 * @description insert Comma 처리
 * @param {*} tab tab
 * @returns {void}
 * @hidden N
 */
scwin.insertComma = function (tab) {

    // form = document.etnListForm;
    const elem = $c.util.getComponent('etnListForm').elements;

    if(tab === 1) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('etnIsuQty') >= 0 ||
                elem[i].name.indexOf('isuOrgnVal') >= 0 ||
                // elem[i].name.indexOf('traceYdMult') >= 0 ||
                elem[i].name.indexOf('lpHdQty') >= 0 ||
                elem[i].name.indexOf('declSpd') >= 0 ||
                elem[i].name.indexOf('halfwyRedmptUnit') >= 0 ||
                elem[i].name.indexOf('etnIsuPrc') >= 0
            )
            fn_ObjValueSetComma(elem[i]);
        }
    } else if(tab === 2) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('expMaxYd') >= 0 ||
                elem[i].name.indexOf('expMaxRedmptPrc') >= 0 ||
                elem[i].name.indexOf('expMaxLossRt') >= 0 ||
                elem[i].name.indexOf('expMinRedmptPrc') >= 0 ||
                elem[i].name.indexOf('basIdx') >= 0 ||
                elem[i].name.indexOf('isuTheoPrc') >= 0 ||
                elem[i].name.indexOf('earyRedmptBas1Idx0') >= 0 ||
                elem[i].name.indexOf('earyRedmptPrc0') >= 0 ||
                elem[i].name.indexOf('earyRedmptBas1Idx') >= 0 ||
                elem[i].name.indexOf('earyRedmptBas2Idx') >= 0 ||
                elem[i].name.indexOf('earyRedmptPrc') >= 0 ||
                elem[i].name.indexOf('rngacrlEarngLwlmtBasIdx') >= 0 ||
                elem[i].name.indexOf('rngacrlEarngUplmtBasIdx') >= 0 ||
                elem[i].name.indexOf('rngacrlTotBzDys') >= 0 ||
                elem[i].name.indexOf('partcRt1RngLwlmtBasIdx') >= 0 ||
                elem[i].name.indexOf('partcRt1RngUplmtBasIdx') >= 0 ||
                elem[i].name.indexOf('partcRt2RngLwlmtBasIdx') >= 0 ||
                elem[i].name.indexOf('partcRt2RngUplmtBasIdx') >= 0 ||
                elem[i].name.indexOf('valuPrc1HistVoltPd') >= 0 ||
                elem[i].name.indexOf('valuPrc2HistVoltPd') >= 0
            ) fn_ObjValueSetComma(elem[i]);
        }
    } else if(tab === 3) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('totAsstAmt') >= 0 ||
                elem[i].name.indexOf('totDebtAmt') >= 0 ||
                elem[i].name.indexOf('totCap') >= 0 ||
                elem[i].name.indexOf('cap') >= 0 ||
                elem[i].name.indexOf('bzProftAmt') >= 0 ||
                elem[i].name.indexOf('ordnincmAmt') >= 0 ||
                elem[i].name.indexOf('netincmAmt') >= 0 ||
                elem[i].name.indexOf('bzActivCashFlowAmt') >= 0 ||
                elem[i].name.indexOf('fbzNetcap') >= 0 ||
                elem[i].name.indexOf('totRiskAmt') >= 0 ||
                elem[i].name.indexOf('reqPersisPrincCapVal') >= 0 ||
                (elem[i].name.indexOf('ncr') >= 0 && elem[i].name.indexOf('ncrAcntclsYymm') < 0) ||
                elem[i].name.indexOf('eqtycap') >= 0 ||
                elem[i].name.indexOf('isuTotamt') >= 0 ||
                elem[i].name.indexOf('isuLimit') >= 0
            ) fn_ObjValueSetComma(elem[i]);
        }
    } else if(tab === 4) {
        for(let i=0; i<elem.length; i++)
        {
            if(elem[i].name.indexOf('totAsstAmt') >= 0 ||
                elem[i].name.indexOf('totDebtAmt') >= 0 ||
                elem[i].name.indexOf('totCap') >= 0 ||
                elem[i].name.indexOf('cap') >= 0 ||
                elem[i].name.indexOf('bzProftAmt') >= 0 ||
                elem[i].name.indexOf('ordnincmAmt') >= 0 ||
                elem[i].name.indexOf('netincmAmt') >= 0 ||
                elem[i].name.indexOf('bzActivCashFlowAmt') >= 0 ||
                elem[i].name.indexOf('basEqtycap') >= 0 ||
                elem[i].name.indexOf('riskAsstVal') >= 0 ||
                elem[i].name.indexOf('etnSrtyPrincCapRto') >= 0 ||
                elem[i].name.indexOf('srtyEqtycap') >= 0 ||
                elem[i].name.indexOf('srtyIsuTotamt') >= 0 ||
                elem[i].name.indexOf('srtyMiscIsuAmt') >= 0 ||
                elem[i].name.indexOf('srtyIsuLimit') >= 0 ||
                elem[i].name.indexOf('lpFbzNetcap') >= 0 ||
                elem[i].name.indexOf('lpTotRiskAmt') >= 0 ||
                elem[i].name.indexOf('lpReqPersisPrincCapVal') >= 0 ||
                elem[i].name.indexOf('lpNcr') >= 0
            ) fn_ObjValueSetComma(elem[i]);
        }
    } else if(tab === 5) {

    }
};
